-- Oxford PPE practice banks (Economics / Philosophy / Politics, 50 each) built from

-- the 2026 interview descriptions (two interviews: Economics; Philosophy & Politics).

-- Practice questions, not real past questions.

insert into public.mock_interview_questions (id, kind, title, description, is_active, is_system, preparation_time, response_time)
values ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'pool', '牛津 PPE · 经济（时事、谜题与逻辑）', '牛津 PPE 经济面试练习题（非真题），按 2026 年面试说明设计：评论近期经济热点新闻（题目取自 2026 年的真实新闻：英国央行加息、伊朗战争与油价、2026 年秋季预算、AI 上市热潮等）；用经济谜题或两难问题分析抽象或现实的经济问题；数学与逻辑思维题。面试中可能需要用纸笔演算并给面试官看推导。', true, true, 30, 180)
on conflict (id) do nothing;

insert into public.mock_interview_bank_questions (bank_id, title, question_type, follow_ups, sort_order)
select v.bank_id::uuid, v.title, v.question_type, v.follow_ups, v.sort_order from (values
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'In November 2026 the Bank of England raised Bank Rate to 4% — its first rise in over three years — saying energy prices pushed up by the conflict in the Middle East could lift inflation to about 5% by mid-2027. Why would raising interest rates help, when the cause is energy prices?', 'video', '[["Raising rates can''t make oil cheaper. So what is it actually trying to stop?"], ["Who is hurt most by the rise, and could it push the UK into recession?"]]'::jsonb, 1),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'The Iran war effectively closed the Strait of Hormuz, through which about a fifth of the world''s oil passes, and oil jumped from around $70 a barrel to over $120 at its peak. Explain how that reaches the price of food in a UK supermarket.', 'video', '[["Why might prices stay high even after the strait reopens?"], ["Which countries gain from an oil shock like this?"]]'::jsonb, 2),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'In his October 2026 Budget, Chancellor John Healey gave a one-off £100 energy payment to about 20 million households in council-tax bands A–D, costing £2.6 billion. Is that a good way to help with energy bills?', 'video', '[["Why use council-tax bands rather than income? What goes wrong?"], ["Would it be better to cap energy prices or cut VAT on energy instead?"]]'::jsonb, 3),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'To pay for energy support, the October 2026 Budget doubled the extra tax on bank profits to 6% for 15 months. Who really pays a tax on bank profits?', 'video', '[["Could it end up being paid by savers or borrowers?"], ["Is it fair to tax one industry because its profits are high right now?"]]'::jsonb, 4),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'The 2026 Budget kept the 5p cut in fuel duty until July 2027, at a cost of about £1.4 billion. Should a government cut fuel taxes when oil prices spike?', 'video', '[["Who benefits most — rich or poor households?"], ["How does this fit with policies to cut carbon emissions?"]]'::jsonb, 5),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'The Chancellor said the UK will spend £14 billion more on debt interest this year, as borrowing costs rose. Why do a government''s borrowing costs go up, and why does it matter?', 'video', '[["Why did the Chancellor want to keep ''headroom'' against his fiscal rules?"], ["Is £15 billion of headroom a lot or a little in an economy of over £2.5 trillion?"]]'::jsonb, 6),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'The 2026 Budget removed the fixed daily ''standing charge'' from gas bills and moved those costs onto the price per unit of gas used. Who gains and who loses?', 'video', '[["How does this change people''s incentive to use less gas?"], ["Why do energy firms charge a fixed fee at all?"]]'::jsonb, 7),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Anthropic''s stock-market listing in November 2026 raised a record $81 billion, amid warnings that AI stocks are a bubble. How would you tell whether a boom is a bubble?', 'video', '[["What happened in the dot-com boom around 2000, and is this different?"], ["If it is a bubble, who would be hurt when it bursts?"]]'::jsonb, 8),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'In the 2026 US midterms, voters in several places backed limits on building new AI data centres, partly over electricity prices. Why might a data centre raise local electricity bills?', 'video', '[["Should a town be able to block a project that benefits the whole country?"], ["How could the costs and benefits be shared more fairly?"]]'::jsonb, 9),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'In June 2026 the US Supreme Court blocked President Trump from firing Federal Reserve governor Lisa Cook, stressing the Fed''s independence. Why do economists think central banks should be independent of politicians?', 'video', '[["What could go wrong if a president controlled interest rates?"], ["Is it democratic to give unelected officials so much power?"]]'::jsonb, 10),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Prime Minister Andy Burnham said a new UK-EU deal at the November 2026 summit could add up to 0.4% to GDP, while ruling out rejoining the single market or customs union. Why would closer trade ties raise GDP?', 'video', '[["What does 0.4% of GDP mean for an ordinary household?"], ["Why is rejoining the single market a much bigger step than a deal on food standards or electricity?"]]'::jsonb, 11),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'UK inflation rose to 3.5% in the autumn of 2026, higher than forecast. If wages are rising at 3% at the same time, are workers better or worse off? Explain.', 'video', '[["Does it matter whether prices or wages started rising first?"], ["Why might the Bank of England worry about a ''wage-price spiral''?"]]'::jsonb, 12),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'The 2026 Budget dropped a planned £12,000 limit on how much people can put into tax-free cash ISAs each year. Why might the government want people to invest in shares rather than keep cash savings?', 'video', '[["Is it the government''s job to tell people how to save?"], ["Who benefits most from tax-free savings accounts?"]]'::jsonb, 13),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Because of the oil shock, some economists warned of ''stagflation'' — rising prices and weak growth at the same time. Why is stagflation so hard for policymakers to fight?', 'video', '[["Should the central bank focus on prices or on jobs?"], ["What tools does the government have that the central bank doesn''t?"]]'::jsonb, 14),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'UK banks'' shares rose after the 2026 Budget because the new bank tax was lower than feared. What does that tell you about how markets work?', 'video', '[["How can a tax rise be ''good news'' for a company?"], ["What does this suggest about how much information prices contain?"]]'::jsonb, 15),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Oil is priced in US dollars. If the pound fell against the dollar during the 2026 oil shock, what would that do to UK petrol prices and inflation?', 'video', '[["Who in the UK would benefit from a weaker pound?"], ["What could the Bank of England do about it?"]]'::jsonb, 16),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Petrol prices in the UK jumped after the Strait of Hormuz was closed, even for petrol that had been refined from oil bought months earlier. Is that profiteering?', 'video', '[["How should a seller price something they already own when its replacement cost rises?"], ["Why do prices seem to rise faster than they fall?"]]'::jsonb, 17),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Why are diamonds so much more expensive than water, when water is essential to life and diamonds are not?', 'video', '[["Would your answer change in a desert?"], ["What does this tell us about what ''value'' means?"]]'::jsonb, 18),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A concert sells out in minutes, and tickets are resold online for five times the price. Is reselling bad?', 'video', '[["How else could the organiser allocate tickets?"], ["Why doesn''t the organiser just charge a higher price?"]]'::jsonb, 19),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'The 2026 Budget sent £100 to 20 million households. If instead every household received £1,000, would people be better off, or would prices just rise?', 'video', '[["Does it depend on whether the economy has spare capacity?"], ["How would you pay for it — and does that change your answer?"]]'::jsonb, 20),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A city wants fewer people to drive. Should it make public transport free?', 'video', '[["Who would actually switch?"], ["How would you pay for it, and is there a better use of the money?"]]'::jsonb, 21),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Why might a firm choose to pay its workers more than the market wage?', 'video', '[["How would that make the firm more profitable?"], ["Why don''t all firms do it?"]]'::jsonb, 22),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A village shares one field where everyone can graze their cows, and the grass is being destroyed. Why does this happen, and what could fix it?', 'video', '[["Is privatising the field the only answer?"], ["What modern problems look like this?"]]'::jsonb, 23),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A drug costs £1 to make but £1,000 to buy. Is that wrong?', 'video', '[["Why might the price be so high?"], ["How else could we reward the companies that invent new medicines?"]]'::jsonb, 24),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Should the government ban the sale of goods that are bad for people, like sugary drinks, or tax them instead?', 'video', '[["What is the difference in effect?"], ["Who pays most of a sugar tax?"]]'::jsonb, 25),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Why do airlines charge different passengers very different prices for the same seat?', 'video', '[["Is that fair?"], ["What would happen if all seats had to cost the same?"]]'::jsonb, 26),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A factory pollutes a river used by a fishing village downstream. What should happen?', 'video', '[["Does it matter who was there first?"], ["Could the two sides solve it without the government?"]]'::jsonb, 27),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Should a country try to produce all of its own food?', 'video', '[["What happens when there is a global crisis?"], ["What does it cost to be self-sufficient?"]]'::jsonb, 28),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A new road is built to reduce traffic, but a few years later traffic is as bad as before. How could that happen?', 'video', '[["Was building the road a mistake?"], ["What would you do instead?"]]'::jsonb, 29),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Is it better to give poor people cash or to give them goods and services like food and housing?', 'video', '[["What are the risks of giving cash?"], ["Who should decide?"]]'::jsonb, 30),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Why do countries trade with each other, even when one country is better at producing everything?', 'video', '[["Can you show this with a simple example?"], ["Who inside a country might lose from trade?"]]'::jsonb, 31),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A university wants to reduce cheating. Should it make the punishment much harsher, or make cheating easier to detect?', 'video', '[["Which works better, and why?"], ["How does this apply to crime more generally?"]]'::jsonb, 32),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Should students pay for their own university education?', 'video', '[["Who benefits from someone going to university?"], ["How would you design a fair funding system?"]]'::jsonb, 33),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Why might a tax cut increase total tax revenue — or might it not?', 'video', '[["Under what conditions?"], ["How would you check whether it happened?"]]'::jsonb, 34),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Some people leave a tip even at a restaurant they will never visit again. Is that irrational?', 'video', '[["What does this say about economic models of behaviour?"], ["Should tipping be replaced by higher wages?"]]'::jsonb, 35),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A football club raises ticket prices and sells more tickets than before. Does that break the law of demand?', 'video', '[["What else might have changed?"], ["Can you think of goods where higher prices raise demand?"]]'::jsonb, 36),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Should rich countries pay poor countries to protect their rainforests?', 'video', '[["How would you make sure the forests are protected?"], ["Why is this a problem markets don''t solve on their own?"]]'::jsonb, 37),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A shop raises a price by 10% and then cuts it by 10%. Is the final price the same as the original? Explain.', 'video', '[["What single change would return it to the original price?"], ["Why does this matter when people talk about inflation and growth?"]]'::jsonb, 38),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Estimate how many coffees are sold in London in one day. Talk us through your reasoning.', 'video', '[["Which number in your estimate are you least sure of?"], ["How would you check it?"]]'::jsonb, 39),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'The OBR forecasts UK growth of about 1.2% in 2026 and 1.0% in 2027. At 1% a year, roughly how long would it take the economy to double in size? Talk us through it.', 'video', '[["How did you estimate it without a calculator?"], ["Why does the difference between 1% and 2% growth matter so much over decades?"]]'::jsonb, 40),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'You are offered £100 today or £110 in a year''s time. Which would you choose and why?', 'video', '[["What would make you change your mind?"], ["What does your answer imply about interest rates?"]]'::jsonb, 41),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Two firms each choose a high or low price. If both choose high they each earn 10; if both choose low, 5 each; if one goes low and the other high, the low one earns 15 and the high one 0. What will they do?', 'video', '[["Why don''t they both just choose high?"], ["What would change if they played this game every week?"]]'::jsonb, 42),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A worker earns £20 an hour, and the government taxes all income above £10,000 at 40%. Does the tax make her work more hours or fewer?', 'video', '[["Can you argue it both ways?"], ["What would you need to know to decide?"]]'::jsonb, 43),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Draw the demand and supply for umbrellas, then show what happens on a rainy day. Explain what you''ve drawn.', 'video', '[["What happens to the price and quantity?"], ["What if umbrella makers also expected the rain?"]]'::jsonb, 44),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A town''s population doubles, but the number of houses stays the same. Use supply and demand to predict what happens to rents.', 'video', '[["Who benefits?"], ["What would happen over the following ten years?"]]'::jsonb, 45),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'If a pizza is cut into 8 slices and 3 people each want as much as possible, how would you divide it fairly? Is ''fair'' the same as ''efficient''?', 'video', '[["What if one person is much hungrier?"], ["How does this relate to taxes?"]]'::jsonb, 46),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A test for a rare disease is 99% accurate. One person in 1,000 has the disease. If you test positive, how likely is it that you have it?', 'video', '[["Why is the answer so surprising?"], ["Where else might this kind of mistake matter in economics or policy?"]]'::jsonb, 47),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'GDP per person rose by 20% in a country over ten years. Does that mean the typical person is 20% better off?', 'video', '[["What could make the typical person worse off?"], ["What would you measure instead?"]]'::jsonb, 48),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'A government can spend £1 billion either on a new hospital or on cutting taxes. How would you decide?', 'video', '[["How would you compare the benefits?"], ["Whose interests would you weigh most?"]]'::jsonb, 49),
  ('a1e2c3d4-0001-4e5f-8a9b-0c1d2e3f4a51', 'Imagine there are only two goods, bread and phones. Bread gets 10% more expensive and phones get 10% cheaper. Has the cost of living gone up or down?', 'video', '[["Does it depend on who you are?"], ["How do official statistics deal with this?"]]'::jsonb, 50)
) as v(bank_id, title, question_type, follow_ups, sort_order)
where not exists (select 1 from public.mock_interview_bank_questions b where b.bank_id = v.bank_id::uuid and b.title = v.title);

insert into public.mock_interview_questions (id, kind, title, description, is_active, is_system, preparation_time, response_time)
values ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'pool', '牛津 PPE · 哲学（哲学谜题）', '牛津 PPE 哲学面试练习题（非真题）：不要求学过哲学，主要考察你如何应对哲学谜题——伦理、自由意志、身份、知识、悖论等，以及你对哲学的兴趣。', true, true, 30, 180)
on conflict (id) do nothing;

insert into public.mock_interview_bank_questions (bank_id, title, question_type, follow_ups, sort_order)
select v.bank_id::uuid, v.title, v.question_type, v.follow_ups, v.sort_order from (values
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'What interests you about philosophy, even if you have never studied it?', 'video', '[["Can you give an example of a philosophical question you have wondered about yourself?"], ["How is a philosophical question different from a scientific one?"]]'::jsonb, 1),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is there a question you think can never be answered? Why is it still worth asking?', 'video', '[["How would you know a question can''t be answered?"], ["What would count as progress on it?"]]'::jsonb, 2),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'What is the difference between a good argument and a persuasive one?', 'video', '[["Can a bad argument have a true conclusion?"], ["Give an example of a persuasive argument you think is bad."]]'::jsonb, 3),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'A runaway train will kill five people unless you pull a lever to send it onto a track where it will kill one. Should you pull the lever?', 'video', '[["What if instead you had to push a person in front of the train to stop it?"], ["If the numbers are the same, why might the two cases feel different?"]]'::jsonb, 4),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is it wrong to lie to someone to spare their feelings?', 'video', '[["What if they later find out?"], ["Is there a difference between lying and not telling the whole truth?"]]'::jsonb, 5),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'If you could save either one stranger''s life or your pet dog, which should you save?', 'video', '[["Does it matter how much you love the dog?"], ["Do animals have rights?"]]'::jsonb, 6),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is it wrong to eat meat?', 'video', '[["Would your answer change if the animals had happy lives?"], ["Where should we draw the line between animals we may eat and those we may not?"]]'::jsonb, 7),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'If no one would ever find out, would it be wrong to steal from a very rich company?', 'video', '[["Why does it matter whether anyone finds out?"], ["Is it wrong because of the harm, or for some other reason?"]]'::jsonb, 8),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Are we morally responsible for things we fail to do, as well as for things we do?', 'video', '[["Is letting someone die as bad as killing them?"], ["How much of your money should you give to help strangers far away?"]]'::jsonb, 9),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Can an action be morally right if it is done for a selfish reason?', 'video', '[["Does the motive matter, or only the result?"], ["Is anyone ever truly unselfish?"]]'::jsonb, 10),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is it fair that some people are born more talented than others? Should society do anything about it?', 'video', '[["Do people deserve the rewards of their talents?"], ["What about the rewards of hard work?"]]'::jsonb, 11),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'If everyone in a society believed slavery was right, would it be right for them?', 'video', '[["Are there moral truths that hold everywhere?"], ["How could we ever know what they are?"]]'::jsonb, 12),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is it ever right to break the law?', 'video', '[["Can you give a historical example?"], ["What would happen if everyone broke laws they disagreed with?"]]'::jsonb, 13),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'You find a wallet with £500 and the owner''s address. Do you have a duty to return it?', 'video', '[["Would it change if the owner were a billionaire?"], ["Where does the duty come from?"]]'::jsonb, 14),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is punishment justified because it deters crime, or because criminals deserve it?', 'video', '[["What if punishing an innocent person would deter more crime?"], ["Can we decide what someone ''deserves''?"]]'::jsonb, 15),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Should we judge people of the past by today''s moral standards?', 'video', '[["Will people in the future judge us harshly? For what?"], ["Does moral progress exist?"]]'::jsonb, 16),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'If a medicine could make people permanently happy with no side effects, should everyone take it?', 'video', '[["Is happiness the only thing that matters?"], ["Would you plug into a machine that gave you a perfect life experience?"]]'::jsonb, 17),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Do we have free will, if every event, including our decisions, has a cause?', 'video', '[["If we don''t, can anyone be blamed for anything?"], ["What would it take to convince you either way?"]]'::jsonb, 18),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'If a perfect copy of you were made on Mars and you were destroyed here, would you have travelled to Mars?', 'video', '[["What if you weren''t destroyed — which one is you?"], ["What makes you the same person over time?"]]'::jsonb, 19),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Could a computer ever think? How would we know?', 'video', '[["Is behaving like a thinker enough?"], ["Could a computer feel pain?"]]'::jsonb, 20),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'How do you know that other people have minds?', 'video', '[["Could everyone around you be a very convincing robot?"], ["Do animals have minds? How would you tell?"]]'::jsonb, 21),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Are you the same person you were when you were five years old?', 'video', '[["What has stayed the same?"], ["If all your memories were erased, would you still be you?"]]'::jsonb, 22),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'If a ship has every one of its planks replaced, one at a time, is it still the same ship?', 'video', '[["What if someone builds a second ship from the old planks — which is the original?"], ["Does this puzzle apply to people?"]]'::jsonb, 23),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is the colour you see when you look at something red the same as the colour I see?', 'video', '[["Could we ever find out?"], ["Would it matter if they were different?"]]'::jsonb, 24),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Can you choose what to believe?', 'video', '[["Try now to believe it is raining. What happens?"], ["If you can''t choose beliefs, can you be blamed for them?"]]'::jsonb, 25),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'How do you know you are not dreaming right now?', 'video', '[["Does it matter if you can''t be certain?"], ["What is the difference between knowing and being very confident?"]]'::jsonb, 26),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Can you know something that is false?', 'video', '[["Can you know something without being able to prove it?"], ["What, if anything, do you know for certain?"]]'::jsonb, 27),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'The sun has risen every day of your life. Does that prove it will rise tomorrow?', 'video', '[["Why do we trust patterns like this?"], ["Is science built on the same assumption?"]]'::jsonb, 28),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'If a tree falls in a forest and no one is around to hear it, does it make a sound?', 'video', '[["What do you mean by ''sound''?"], ["Does this show the disagreement is about words, or about the world?"]]'::jsonb, 29),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Do numbers exist? Where are they?', 'video', '[["If no humans existed, would 2 + 2 still equal 4?"], ["Did we invent mathematics or discover it?"]]'::jsonb, 30),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is there a difference between something being true and everyone believing it?', 'video', '[["Can a whole society be wrong about a fact?"], ["Is truth the same in science and in morality?"]]'::jsonb, 31),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Should you believe something just because an expert tells you it is true?', 'video', '[["What if experts disagree?"], ["How do you decide whom to trust?"]]'::jsonb, 32),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is it rational to believe in something you cannot see, like electrons or atoms?', 'video', '[["How is that different from believing in ghosts?"], ["What makes a belief reasonable?"]]'::jsonb, 33),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'A teacher says there will be a surprise test next week, on a day you can''t predict. Can there be a surprise test?', 'video', '[["Where does the reasoning that it can''t happen go wrong?"], ["What does ''surprise'' mean here?"]]'::jsonb, 34),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'One grain of sand is not a heap. Adding one grain to something that isn''t a heap never makes it a heap. So are there no heaps?', 'video', '[["Where does the argument go wrong?"], ["What other words have this problem — ''bald'', ''tall'', ''adult''?"]]'::jsonb, 35),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'The sentence ''This sentence is false'' — is it true or false?', 'video', '[["Does this show something is wrong with language, or with logic?"], ["Can you think of a similar puzzle?"]]'::jsonb, 36),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Achilles gives a tortoise a head start. By the time he reaches where the tortoise was, it has moved on a little. Can Achilles ever overtake it?', 'video', '[["Where does the argument go wrong?"], ["Does maths fully solve the puzzle?"]]'::jsonb, 37),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is a perfect copy of the Mona Lisa worth as much as the original? Why or why not?', 'video', '[["If no expert could tell them apart, what is the difference?"], ["Does the same apply to a copy of a song or a file?"]]'::jsonb, 38),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'If you promise to do something and then forget the promise, have you done anything wrong?', 'video', '[["Is forgetting ever blameworthy?"], ["Does an obligation need someone who remembers it?"]]'::jsonb, 39),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Imagine a pill that would make you believe something you know is false right now, but would make you happier. Would you take it?', 'video', '[["Is it better to know the truth than to be happy?"], ["Is it rational to want true beliefs?"]]'::jsonb, 40),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is it possible to think about nothing?', 'video', '[["What happens when you try?"], ["Does ''nothing'' refer to anything?"]]'::jsonb, 41),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Can something be both good and beautiful but not useful? Is usefulness what makes things valuable?', 'video', '[["What makes art valuable?"], ["Could a meal be a work of art?"]]'::jsonb, 42),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'If you were told the world ends tomorrow, would anything you did today still matter?', 'video', '[["Does meaning depend on the future?"], ["Do our lives matter if the universe will one day end?"]]'::jsonb, 43),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Can a group — a company, a country — be responsible for something, or only the people in it?', 'video', '[["Can a country apologise?"], ["Who should pay for a company''s mistakes?"]]'::jsonb, 44),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is a law that nobody obeys still a law?', 'video', '[["What makes something a law at all?"], ["Is an unjust law a real law?"]]'::jsonb, 45),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'If two people disagree about whether a joke is funny, can one of them be wrong?', 'video', '[["Is humour like taste in food?"], ["Is the same true of beauty, or of morality?"]]'::jsonb, 46),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is it possible to be harmed by something you never find out about — for example, being lied about behind your back?', 'video', '[["Can the dead be harmed?"], ["What does this say about what harm is?"]]'::jsonb, 47),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Can you give a reason for using reason?', 'video', '[["If not, is it irrational to trust reasoning?"], ["What else could you rely on?"]]'::jsonb, 48),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'Is it ever right to treat a person only as a means to an end, even to save many others?', 'video', '[["What does it mean to treat someone ''only'' as a means?"], ["Do we treat shop workers as means? Is that wrong?"]]'::jsonb, 49),
  ('a1e2c3d4-0002-4e5f-8a9b-0c1d2e3f4a52', 'If a robot became as intelligent and sensitive as a person, would switching it off be wrong?', 'video', '[["What would it need to have for that to be wrong?"], ["Is being human what matters, or something else?"]]'::jsonb, 50)
) as v(bank_id, title, question_type, follow_ups, sort_order)
where not exists (select 1 from public.mock_interview_bank_questions b where b.bank_id = v.bank_id::uuid and b.title = v.title);

insert into public.mock_interview_questions (id, kind, title, description, is_active, is_system, preparation_time, response_time)
values ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'pool', '牛津 PPE · 政治（时事与政治概念）', '牛津 PPE 政治面试练习题（非真题）：讨论近期政治热点（取自 2026 年的真实新闻：伯纳姆接任首相、英欧峰会与脱欧、美国中期选举、伊朗战争、美联储独立性等）、民主与权力等政治概念，以及历史、政治或社会学课上学过的话题。', true, true, 30, 180)
on conflict (id) do nothing;

insert into public.mock_interview_bank_questions (bank_id, title, question_type, follow_ups, sort_order)
select v.bank_id::uuid, v.title, v.question_type, v.follow_ups, v.sort_order from (values
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'In July 2026 Andy Burnham became Prime Minister after Keir Starmer resigned — without a general election. Is it democratic for a party to change the prime minister between elections?', 'video', '[["Should a new prime minister have to call an election soon?"], ["Burnham has said there will be no snap election within 12 months. Is that the right call?"]]'::jsonb, 1),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'To give Andy Burnham a route back into Parliament, the Labour MP for Makerfield resigned so that Burnham could stand in the by-election, which he won with 55% of the vote. Is it right for an MP to give up a seat so a party figure can take it?', 'video', '[["Whose seat is it — the MP''s, the party''s or the voters''?"], ["Does a big win in the by-election settle the question?"]]'::jsonb, 2),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Andy Burnham is reported to be the UK''s seventh prime minister in ten years. Does frequent change at the top matter for how a country is governed?', 'video', '[["What does it do to long-term policy?"], ["Is it a sign that the system is working or failing?"]]'::jsonb, 3),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Burnham has proposed a ''Makerfield Test'': judging every policy by whether it makes life better or worse for the least well-off communities. Is that a good rule for government?', 'video', '[["What policies might fail the test but still be worth doing?"], ["Who decides which communities count as the least well off?"]]'::jsonb, 4),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Ahead of the UK-EU summit in November 2026, Burnham said the post-Brexit settlement ''has not worked'', but ruled out rejoining the single market or customs union this Parliament. Should a government be bound by red lines in its manifesto when circumstances change?', 'video', '[["Does a 2016 referendum still bind the country today?"], ["Should any move to rejoin require another referendum or a general election?"]]'::jsonb, 5),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'In the Makerfield by-election, Reform UK came second with about 35% of the vote, and British politics is more fragmented than ever. Why have new parties grown so quickly?', 'video', '[["Does first-past-the-post still work when five parties have real support?"], ["Is fragmentation good or bad for voters?"]]'::jsonb, 6),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'In the November 2026 US midterms, Democrats won control of both the House and the Senate, amid voters'' frustration over high prices and the Iran war. What does ''divided government'' mean for the last two years of Trump''s presidency?', 'video', '[["Trump says he will veto Democratic bills. Is gridlock a failure of the system or part of its design?"], ["Are midterm elections a fair referendum on a president?"]]'::jsonb, 7),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'The United States and Israel went to war with Iran in 2026. Who should have the power to take a country to war — the leader, the legislature or the people?', 'video', '[["What role did the US Congress play, and what role should it play?"], ["How should voters judge a war''s success?"]]'::jsonb, 8),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'In June 2026 the US Supreme Court stopped the President from firing a Federal Reserve governor, but in another case let him fire officials of other regulators. Should unelected agencies be independent of the President?', 'video', '[["Why treat the central bank differently from other agencies?"], ["Who holds independent agencies accountable?"]]'::jsonb, 9),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'In the 2026 midterms some local voters approved limits on new AI data centres, while national leaders want more of them. When local and national interests clash, who should decide?', 'video', '[["Is this like opposition to wind farms or new housing?"], ["Should communities be paid to accept national infrastructure?"]]'::jsonb, 10),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'In its October 2026 Budget the UK pledged an extra £10 billion of economic and military aid to Ukraine, while households struggle with energy bills. How should a government weigh spending abroad against help at home?', 'video', '[["Is supporting Ukraine in Britain''s national interest? Why?"], ["Should voters have a direct say on decisions like this?"]]'::jsonb, 11),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'A Labour defence minister resigned in 2026 over defence spending. Should a minister resign when they disagree with government policy?', 'video', '[["What is collective cabinet responsibility, and is it a good idea?"], ["When is resigning more effective than staying to argue inside?"]]'::jsonb, 12),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Burnham wants a ''Manchester Compact on AI'' when the UK hosts the G20 next year. Can countries agree global rules for AI?', 'video', '[["Why might countries resist?"], ["Should AI companies help write the rules?"]]'::jsonb, 13),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Anthropic, an AI company, listed on the stock market in November 2026, and Democrats have vowed to crack down on the AI industry. Should powerful technology companies be regulated by elected politicians or by independent experts?', 'video', '[["What could go wrong either way?"], ["Do tech companies already have political power?"]]'::jsonb, 14),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Should a country''s leaders be bound by international law when deciding to use force, as in the 2026 war with Iran?', 'video', '[["What happens when a powerful country ignores it?"], ["Is national sovereignty more important?"]]'::jsonb, 15),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'What makes a country a democracy?', 'video', '[["Is a country with free elections but no free press a democracy?"], ["Can a democracy vote to end democracy?"]]'::jsonb, 16),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Why should anyone obey the government?', 'video', '[["Did you ever agree to be governed?"], ["Is there ever a duty to disobey?"]]'::jsonb, 17),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Is it more important for a government to be effective or to be democratic?', 'video', '[["Can you think of an effective non-democratic government?"], ["Why might democracies be slow?"]]'::jsonb, 18),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Should the majority always get its way?', 'video', '[["How should minorities be protected?"], ["Who decides which rights the majority can''t override?"]]'::jsonb, 19),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Is freedom of speech absolute? Where would you draw the line?', 'video', '[["Should offensive speech be allowed?"], ["Who should enforce the line?"]]'::jsonb, 20),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Is it the government''s job to make people equal?', 'video', '[["Equal in what — income, opportunity, or something else?"], ["What would you sacrifice for more equality?"]]'::jsonb, 21),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'What is a ''right''? Where do rights come from?', 'video', '[["Can rights conflict with each other?"], ["Is there a right to healthcare?"]]'::jsonb, 22),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Should politicians do what their voters want, or what they think is best?', 'video', '[["What if voters want something harmful?"], ["Does it matter whether they promised it in an election?"]]'::jsonb, 23),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Is it ever justified to use violence for a political cause?', 'video', '[["Can you think of a case history judges kindly?"], ["What makes it different from terrorism?"]]'::jsonb, 24),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Should judges have the power to overturn laws passed by elected politicians?', 'video', '[["Is that undemocratic?"], ["Who should protect the constitution?"]]'::jsonb, 25),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Is it better for a country to have a written constitution?', 'video', '[["How do countries without one protect rights?"], ["Should a constitution be hard to change?"]]'::jsonb, 26),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Ten years after the Brexit referendum, there are calls for a new vote on the UK''s relationship with the EU. Is a referendum a good way to make big decisions?', 'video', '[["Should a second referendum be held if public opinion changes?"], ["Should a referendum need more than 50% to pass?"]]'::jsonb, 27),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Can a state be neutral between different religions and ways of life?', 'video', '[["Should religious symbols be allowed in schools?"], ["What happens when religious beliefs conflict with the law?"]]'::jsonb, 28),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Should a country''s head of state be elected?', 'video', '[["What is the case for a monarchy?"], ["What does a president do that a prime minister doesn''t?"]]'::jsonb, 29),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Reform UK, the Greens and the Liberal Democrats all now win large shares of the vote. Is first-past-the-post still the right voting system for the UK, or should it move to proportional representation?', 'video', '[["Which produces stronger governments?"], ["Which is fairer to voters?"]]'::jsonb, 30),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Why do some countries become democracies and others don''t?', 'video', '[["Does economic growth lead to democracy?"], ["Can democracy be imposed from outside?"]]'::jsonb, 31),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'The 2026 Budget planned to let regional mayors keep part of local income tax and business rates. Should power and money move from Westminster to regions and cities?', 'video', '[["What decisions should be made locally?"], ["What are the risks if poorer regions raise less?"]]'::jsonb, 32),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Do international organisations like the United Nations still matter?', 'video', '[["Why do great powers have a veto in the Security Council?"], ["How would you reform it?"]]'::jsonb, 33),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'The UK has had seven prime ministers in ten years, while some countries keep one leader for decades. Which is the bigger problem for a democracy?', 'video', '[["Should there be term limits?"], ["What if voters keep choosing the same leader freely?"]]'::jsonb, 34),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Why do some countries spend much more on welfare than others?', 'video', '[["Is it about values, history or wealth?"], ["Does a bigger welfare state make people less willing to work?"]]'::jsonb, 35),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Should a country ever intervene in another country''s affairs, for example to stop human rights abuses?', 'video', '[["Who decides when to intervene?"], ["Can you think of an intervention that went well, or badly?"]]'::jsonb, 36),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Choose a historical event you have studied. What does it teach us about politics today?', 'video', '[["Is it dangerous to draw lessons from history?"], ["Would a historian from another country tell the story differently?"]]'::jsonb, 37),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Do individuals change history, or do larger forces like economics and technology?', 'video', '[["Give an example on each side."], ["Would the event have happened anyway without that person?"]]'::jsonb, 38),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Revolutions often end with a new government as harsh as the old one. Why?', 'video', '[["Can you think of a revolution that succeeded?"], ["Is reform always better than revolution?"]]'::jsonb, 39),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Is social class still important in politics?', 'video', '[["Has it been replaced by age, education or geography?"], ["How would you measure it?"]]'::jsonb, 40),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Does a country''s education system shape its politics?', 'video', '[["Should schools teach politics?"], ["Can schools be politically neutral?"]]'::jsonb, 41),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Should a government apologise for wrongs done by previous governments long ago?', 'video', '[["Should it also pay compensation?"], ["Who exactly is apologising, and to whom?"]]'::jsonb, 42),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'What is the role of the media in a democracy?', 'video', '[["Can media be too powerful?"], ["Should public broadcasters be funded by the state?"]]'::jsonb, 43),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Is protest an effective way to change government policy?', 'video', '[["What makes some protests succeed?"], ["Should disruptive protest be restricted?"]]'::jsonb, 44),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'A government can save money by closing rural hospitals, which would make healthcare better overall but worse for some towns. Should it?', 'video', '[["How should the views of the towns be weighed?"], ["Is this a decision for experts or for voters?"]]'::jsonb, 45),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Should people who don''t vote lose some benefits, to encourage voting?', 'video', '[["Is that a fair way to protect democracy?"], ["What would compulsory voting change?"]]'::jsonb, 46),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'If the energy crisis from the Iran war got worse, should a government be allowed to ration energy or fuel? When can it suspend normal economic freedoms?', 'video', '[["Who decides when the emergency is over?"], ["Can you think of a time this went too far?"]]'::jsonb, 47),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Elections like the 2026 US midterms cost billions of dollars. Should rich people and companies be allowed to give unlimited money to political campaigns?', 'video', '[["Is giving money a form of free speech?"], ["How else could campaigns be funded?"]]'::jsonb, 48),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'If a policy is popular but experts say it will cause harm, what should a democratic government do?', 'video', '[["Should experts have more power?"], ["Have experts been wrong before?"]]'::jsonb, 49),
  ('a1e2c3d4-0003-4e5f-8a9b-0c1d2e3f4a53', 'Should prisoners have the right to vote?', 'video', '[["What is the purpose of taking it away?"], ["Does it matter what crime they committed?"]]'::jsonb, 50)
) as v(bank_id, title, question_type, follow_ups, sort_order)
where not exists (select 1 from public.mock_interview_bank_questions b where b.bank_id = v.bank_id::uuid and b.title = v.title);

insert into public.mock_interview_questions (id, kind, title, school, program, description, is_active, is_system, preparation_time, response_time, blueprint, sim_shuffle, sim_retakes)
